CREATE OR REPLACE FUNCTION public.default_incident_categories() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT '[{"value":"traffic","label":"Trânsito intenso","priority":"attention","requires_description":false},{"value":"accident","label":"Acidente, bloqueio ou interdição","priority":"high","requires_description":true},{"value":"pickup_delay","label":"Atraso na coleta","priority":"attention","requires_description":false},{"value":"delivery_delay","label":"Atraso na entrega","priority":"attention","requires_description":false},{"value":"loading_wait","label":"Aguardando carregamento","priority":"informative","requires_description":false},{"value":"unloading_wait","label":"Aguardando descarga","priority":"attention","requires_description":false},{"value":"vehicle_problem","label":"Problema no veículo","priority":"high","requires_description":true},{"value":"breakdown","label":"Pneu furado ou pane mecânica","priority":"high","requires_description":true},{"value":"address_access","label":"Problema de acesso ao endereço","priority":"attention","requires_description":true},{"value":"wrong_address","label":"Endereço incorreto ou destinatário não localizado","priority":"high","requires_description":true},{"value":"client_absent","label":"Cliente ou responsável ausente","priority":"attention","requires_description":false},{"value":"cargo_issue","label":"Divergência na carga ou documentação","priority":"high","requires_description":true},{"value":"missing_documents","label":"Falta de documentos","priority":"attention","requires_description":true},{"value":"document_problem","label":"Problema com CT-e, NF ou comprovantes","priority":"attention","requires_description":true},{"value":"security","label":"Problema de segurança","priority":"critical","requires_description":true},{"value":"guidance","label":"Solicitação de orientação à operação","priority":"informative","requires_description":true},{"value":"other","label":"Outros","priority":"attention","requires_description":true}]'::jsonb; $$;
CREATE OR REPLACE FUNCTION public.get_incident_categories() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (public.can_manage_operation_board(auth.uid()) OR public.has_role(auth.uid(),'driver')) THEN RAISE EXCEPTION 'Not authorized'; END IF; RETURN coalesce((SELECT value FROM public.app_settings WHERE key='driver_incident_categories'),public.default_incident_categories()); END; $$;
REVOKE ALL ON FUNCTION public.get_incident_categories() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_incident_categories() TO authenticated;
CREATE OR REPLACE FUNCTION public.save_incident_categories(_categories jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Not authorized'; END IF; IF jsonb_typeof(_categories)<>'array' OR jsonb_array_length(_categories) NOT BETWEEN 1 AND 40 THEN RAISE EXCEPTION 'Invalid categories'; END IF; FOR c IN SELECT value FROM jsonb_array_elements(_categories) LOOP IF coalesce(c->>'value','') !~ '^[a-z][a-z_]{1,49}$' OR length(trim(coalesce(c->>'label',''))) NOT BETWEEN 1 AND 120 OR coalesce(c->>'priority','') NOT IN ('informative','attention','high','critical') OR jsonb_typeof(c->'requires_description') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid category'; END IF; END LOOP; IF (SELECT count(DISTINCT value->>'value') FROM jsonb_array_elements(_categories)) <> jsonb_array_length(_categories) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_categories) WHERE value->>'value'='other' AND value->>'requires_description'='true') THEN RAISE EXCEPTION 'Unique categories and Other explanation required'; END IF; INSERT INTO public.app_settings(key,value,updated_by) VALUES('driver_incident_categories',_categories,auth.uid()) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_by=excluded.updated_by,updated_at=now(); END; $$;
REVOKE ALL ON FUNCTION public.save_incident_categories(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_incident_categories(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_driver_incident(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; iid uuid; c jsonb; req uuid; lat double precision; lng double precision; stage text; driver_name text; summary text; BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'driver') THEN RAISE EXCEPTION 'Driver required'; END IF;
req:=(_data->>'request_id')::uuid; IF req IS NULL OR _data->>'safe_stop' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Safe stop confirmation required'; END IF;
SELECT id INTO iid FROM public.incidents WHERE reported_by=auth.uid() AND request_id=req; IF FOUND THEN RETURN iid; END IF;
SELECT * INTO o FROM public.orders WHERE id=(_data->>'order_id')::uuid AND driver_id=auth.uid() AND deleted_at IS NULL AND status NOT IN ('delivered','finalized','cancelled') FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Active assigned freight required'; END IF;
SELECT value INTO c FROM jsonb_array_elements(public.get_incident_categories()) WHERE value->>'value'=_data->>'type'; IF c IS NULL THEN RAISE EXCEPTION 'Invalid category'; END IF;
IF length(coalesce(_data->>'description',''))>4000 OR ((c->>'requires_description')::boolean AND length(trim(coalesce(_data->>'description','')))<3) THEN RAISE EXCEPTION 'Explanation required'; END IF;
lat:=(_data->>'latitude')::double precision; lng:=(_data->>'longitude')::double precision;
IF (lat IS NULL) IS DISTINCT FROM (lng IS NULL) OR lat NOT BETWEEN -90 AND 90 OR lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Invalid location'; END IF;
IF lat IS NOT NULL AND (_data->>'location_captured_at' IS NULL OR (_data->>'location_captured_at')::timestamptz>now()+interval '1 minute') THEN RAISE EXCEPTION 'Invalid capture time'; END IF;
IF _data->>'driver_eta' IS NOT NULL AND (_data->>'driver_eta')::timestamptz<=now() THEN RAISE EXCEPTION 'Forecast must be in the future'; END IF;
stage:=CASE WHEN o.status::text IN ('at_pickup','loading','loaded') THEN 'loading' WHEN o.status::text IN ('picked_up','out_for_delivery','in_transit','near_destination','arriving_destination') THEN 'transit' WHEN o.status::text IN ('at_destination','unloading') THEN 'unloading' ELSE 'pickup_travel' END;
INSERT INTO public.incidents(order_id,reported_by,type,description,severity,priority,request_id,vehicle_id,trip_stage,latitude,longitude,location_captured_at,driver_eta,affects_deadline) VALUES(o.id,auth.uid(),c->>'value',nullif(trim(_data->>'description'),''),CASE WHEN c->>'priority' IN ('high','critical') THEN 'high' WHEN c->>'priority'='informative' THEN 'low' ELSE 'medium' END,c->>'priority',req,o.vehicle_id,stage,lat,lng,CASE WHEN lat IS NOT NULL THEN (_data->>'location_captured_at')::timestamptz END,(_data->>'driver_eta')::timestamptz,coalesce((_data->>'affects_deadline')::boolean,false)) ON CONFLICT(reported_by,request_id) WHERE request_id IS NOT NULL DO NOTHING RETURNING id INTO iid;
IF iid IS NULL THEN SELECT id INTO iid FROM public.incidents WHERE reported_by=auth.uid() AND request_id=req; RETURN iid; END IF;
SELECT coalesce(full_name,'Motorista') INTO driver_name FROM public.profiles WHERE id=auth.uid();
INSERT INTO public.incident_updates(incident_id,actor_id,actor_name,action,message) VALUES(iid,auth.uid(),coalesce(driver_name,'Motorista'),'created',nullif(trim(_data->>'description'),''));
INSERT INTO public.order_events(order_id,event_type,actor_id,payload) VALUES(o.id,'driver_incident_created',auth.uid(),jsonb_build_object('incident_id',iid,'category',c->>'label','affects_deadline',coalesce((_data->>'affects_deadline')::boolean,false)));
summary:='Nova ocorrência: '||(c->>'label')||'. Motorista: '||coalesce(driver_name,'Motorista')||'. Frete: '||o.code||'. Cliente: '||coalesce(o.client_name,'Não informado')||'. Obra: '||coalesce((SELECT name FROM public.works WHERE id=o.work_id),'Não informada')||'. Horário: '||to_char(now() AT TIME ZONE 'America/Sao_Paulo','DD/MM/YYYY HH24:MI');
INSERT INTO public.notifications(user_id,type,title,body,data) SELECT DISTINCT user_id,'driver_incident_created','Nova ocorrência da viagem',summary,jsonb_build_object('incident_id',iid,'order_id',o.id) FROM public.user_roles WHERE role IN ('admin','logistics','supervisor','operacional') AND user_id<>auth.uid(); RETURN iid; END; $$;
REVOKE ALL ON FUNCTION public.create_driver_incident(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_driver_incident(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.link_incident_file(_incident uuid,_path text,_label text,_mime text,_size bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.incidents WHERE id=_incident AND reported_by=auth.uid() AND closed_at IS NULL) OR split_part(_path,'/',1)<>_incident::text OR length(_label) NOT BETWEEN 1 AND 200 OR _size NOT BETWEEN 1 AND 20971520 OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='incident-files' AND name=_path AND owner_id=auth.uid()::text) THEN RAISE EXCEPTION 'Invalid attachment'; END IF; INSERT INTO public.incident_files(incident_id,file_path,label,mime_type,size_bytes,uploaded_by) VALUES(_incident,_path,_label,_mime,_size,auth.uid()) ON CONFLICT(file_path) DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.link_incident_file(uuid,text,text,text,bigint) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.link_incident_file(uuid,text,text,text,bigint) TO authenticated;